class StockReport:
    def __init__(self, warehouses):
        self.warehouses = warehouses

    def low_stock(self, threshold=5):
        result = {}
        for warehouse, stock in self.warehouses.items():
            for sku, qty in stock.items():
                if qty < threshold:
                    if sku not in result:
                        result[sku] = []
                    if qty == 0:
                        result[sku].append((warehouse, "out"))
                    else:
                        result[sku].append((warehouse, "low"))
        return result

    def total(self, sku):
        return sum(stock.get(sku, 0) for stock in self.warehouses.values())

