from stock.report import StockReport

DATA = {"north": {"pen": 2, "cup": 9}, "south": {"pen": 0, "cup": 7}}


def test_low_stock():
    assert StockReport(DATA).low_stock() == {"pen": [("north", "low"), ("south", "out")]}


def test_total():
    assert StockReport(DATA).total("cup") == 16

