from stock.report import StockReport


def test_threshold_and_order():
    data = {"a": {"x": 1, "y": 3}, "b": {"y": 0, "z": 4}}
    report = StockReport(data)
    assert report.low_stock(4) == {"x": [("a", "low")], "y": [("a", "low"), ("b", "out")]}
    assert report.low_stock(0) == {}
    assert list(report.low_stock(10)) == ["x", "y", "z"]
